package org.sleepwell.app;

import android.content.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.Test;import org.junit.runner.RunWith;import org.json.*;import java.util.*;import static org.junit.Assert.*;

@RunWith(AndroidJUnit4.class)
public final class BarcodeCodeStorageTest {
    @Test public void legacyQrPortableSettingsStayExactlyThreeFields()throws Exception{MorningCode old=new MorningCode("Bathroom",MorningCode.digest("old private QR"),MathSettings.LEGACY);JSONObject encoded=MorningCodeJson.encode(old);assertEquals(3,encoded.length());assertFalse(encoded.has("format"));MorningCode decoded=MorningCodeJson.decode(new JSONObject(encoded.toString()));assertEquals(MorningBarcode.QR,decoded.format);assertEquals(encoded.toString(),MorningCodeJson.encode(decoded).toString());assertEquals(old.hash,decoded.hash);}
    @Test public void barcodeFormatRoundTripsAndUnknownOrSmuggledFieldsAreRejected()throws Exception{MorningCode code=new MorningCode("Kitchen",MorningBarcode.fingerprint("CODE_128","MORNING-42"),MathSettings.LEGACY,"CODE_128");JSONObject encoded=MorningCodeJson.encode(code);assertEquals(4,encoded.length());assertTrue(code.sameIdentity(MorningCodeJson.decode(encoded)));assertFalse(code.sameIdentity(new MorningCode(code.label,code.hash,code.fallback,"CODE_39")));for(Object bad:List.of("PDF_417",MorningBarcode.QR,1,new JSONArray())){JSONObject invalid=new JSONObject(encoded.toString()).put("format",bad);assertThrows(JSONException.class,()->MorningCodeJson.decode(invalid));}assertThrows(JSONException.class,()->MorningCodeJson.decode(new JSONObject(encoded.toString()).put("payload","forbidden")));JSONObject stripped=new JSONObject(encoded.toString());stripped.remove("format");MorningCode legacy=MorningCodeJson.decode(stripped);assertEquals(MorningBarcode.QR,legacy.format);assertFalse(code.sameIdentity(legacy));}
    @Test public void privateAlarmDefaultsBackupRestorePreserveExactTypedIdentityWithoutRawPayload()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();String database="barcode-storage-"+UUID.randomUUID();String payload="SLEEPWELL-KITCHEN-731";try{try(Store store=new Store(c,database)){MorningCode code=new MorningCode("Kitchen",MorningBarcode.fingerprint("CODE_128",payload),new MathSettings(MathSettings.Level.HARD,8,true),"CODE_128");Alarm alarm=new Alarm(1);alarm.enabled=false;alarm.setRoutine(new ChallengeRoutine(List.of(new ChallengeRoutine.Task("QR code",1,0,MathSettings.LEGACY,code))));store.save(alarm);JSONObject before=store.backup();assertFalse(before.toString().contains(payload));Backup.validate(before);Alarm defaults=AlarmDefaultsJson.decode(AlarmDefaultsJson.encode(new AlarmDefaults(alarm))).create(2);assertTrue(code.sameIdentity(defaults.challenges().tasks.get(0).code));Backup.restoreData(store,before);assertTrue(code.sameIdentity(store.alarm(1).challenges().tasks.get(0).code));String stable=store.backup().toString();JSONObject broken=new JSONObject(before.toString());broken.getJSONArray("alarms").getJSONObject(0).getJSONArray("routine").getJSONObject(0).getJSONObject("code").put("format","UNKNOWN");assertThrows(JSONException.class,()->Backup.restoreData(store,broken));assertEquals(stable,store.backup().toString());}try(Store reopened=new Store(c,database)){assertEquals("CODE_128",reopened.alarm(1).challenges().tasks.get(0).code.format);}}finally{c.deleteDatabase(database);}}
}
